package ro.filegrid.download;

import java.time.Duration;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.bind.DefaultValue;
import org.springframework.util.unit.DataSize;

/**
 * {@code filegrid.download} configuration (C8).
 *
 * @param linkSecret       HMAC key for signed links, base64 ({@code DOWNLOAD_LINK_SECRET}, generated by
 *                         {@code scripts/start.*}); at least 32 bytes after decoding
 * @param linkTtl          how long a link stays valid (15 minutes)
 * @param preVerifyMaxSize files up to this size are fully read and hash-verified BEFORE sending; larger ones are
 *                         verified while streaming (16 MB by default)
 */
@ConfigurationProperties("filegrid.download")
public record DownloadProperties(String linkSecret,
                                 @DefaultValue("15m") Duration linkTtl,
                                 @DefaultValue("16MB") DataSize preVerifyMaxSize) {
}
